                    "SELECT window_id, version, node_count, created_nanos, updated_nanos"
                            + " FROM canal_graph WHERE window_id = ?", CANAL_GRAPH_MAPPER, windowId);
        } catch (EmptyResultDataAccessException e) {
            return null;
        }
    }

