        throw ApiException.conflict("TRANSFER_FLOW_MISMATCH", "渠网窗口转让要求源与目标流量一致");
    }
    if (lockedSource.heldAmount().compareTo(amount) != 0) {
        throw ApiException.conflict("TRANSFER_PARTIAL_NOT_ALLOWED",
                "渠网窗口转让须一次性转出全部持有额度");
    }
}

