        postJson("/api/allocations", canalAllocationBody(key("ac"), key("ak"), windowId, "u", "1",
                List.of(new String[]{"A", "C"}), "1"), "alice", 400);
        // 空路径
        postJson("/api/allocations", canalAllocationBody(key("ac"), key("ak"), windowId, "u", "1",
                List.of(), "1"), "alice", 400);
        // 缺 flowRate / 缺 path
        postJson("/api/allocations", canalAllocationBody(key("ac"), key("ak"), windowId, "u", "1",
                List.of(new String[]{"A", "B"}), null), "alice", 400);
        postJson("/api/allocations", canalAllocationBody(key("ac"), key("ak"), windowId, "u", "1",
                null, "1"), "alice", 400);
        // 流量非整数、零、负数
        postJson("/api/allocations", canalAllocationBody(key("ac"), key("ak"), windowId, "u", "1",
                List.of(new String[]{"A", "B"}), "1.5"), "alice", 400);
        postJson("/api/allocations", canalAllocationBody(key("ac"), key("ak"), windowId, "u", "1",
