                List.of(new String[]{"A", "B", "10"}));
        String requestId = key("rv");
        // 十进制按值：先以 "8.0" 修订，再以 "8" 重放同参
        JsonNode first = objectMapper.readTree(revise(windowId,
                revisionBody(requestId, 1, List.of(new String[]{"A", "B", "8.0"}), null, null), "ops", 200)
                .getResponse().getContentAsString());
        JsonNode replay = objectMapper.readTree(revise(windowId,
                revisionBody(requestId, 1, List.of(new String[]{"A", "B", "8"}), null, null), "ops", 200)
                .getResponse().getContentAsString());
        assertEquals(first, replay);
        // 版本只推进一次
        assertEquals(2, graph(windowId).get("version").asInt());
        // 同 requestId 改参（容量/操作者）-> 409
        revise(windowId, revisionBody(requestId, 1, List.of(new String[]{"A", "B", "9"}), null, null),
                "ops", 409);
        revise(windowId, revisionBody(requestId, 1, List.of(new String[]{"A", "B", "8"}), null, null),
                "other", 409);
    }

